export default [{"id":1078,"question":"السائل يسأل عن حكم تعريف الضَّالة في المسجد؟","title":"ما حكم تعريف الضَّالة في المسجد؟","answer":"الجواب:\nبسم الله، والصلاة والسلام على رسول الله.\nأما بعد: فتعريف الضَّالة في المسجد أمرٌ لا يجوز، ولكن يقف عند الباب من خارجٍ ويقول ما في النفس: مَن دلَّ على بعيري، على سيارتي، على خروفي، على كذا، على كذا، لا بأس. أما من الداخل فلا، النبي ﷺ أنكر على مَن فعل ذلك وقال: مَن سمع رجلًا ينشد ضالةً في المسجد فليقل: لا ردَّها الله عليك؛ لأنَّ المساجد لم تُبْنَ لهذا الأمر، لم تُبْنَ لإنشاد الضَّوال والسؤال عمَّا ضاع لك، ولكن يقف خارج المسجد ويسأل عمَّا بدا له.","link":"https://binbaz.org.sa/fatwas/21139/ما-حكم-تعريف-الضالة-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0935ما حكم تعريف الضالة في المسجد؟ ابن باز فتاوى المحاضرات.mp3","categories":["اللقطة واللقيط"]},{"id":2170,"question":"والسؤال الآخر يقول: وجدتُ شاةً صغيرةً ثم ربيتها، وفي السنة الأولى لم أعَرِّفها، ثم بعد ذلك يقيت معي، فما الذي يجب عليَّ؟","title":"حكم ضالة الغنم لمن التقطها","answer":"الجواب:\nيُعَرِّفها.\nس: في السنة الثانية؟\nج: نعم.\nس: إذا ماتت الشاة وهي عندي؟\nج: إذن فلا حاجةَ إلى أن يُعرِّفها.\nس: ألا يغرم ثمنها؟\nج: لا، طالما أنه ما تعدَّى عليها لا يغرمها.","link":"https://binbaz.org.sa/fatwas/22291/حكم-ضالة-الغنم-لمن-التقطها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم في ضالة الغنم.mp3","categories":["اللقطة واللقيط"]},{"id":3359,"question":"بالنسبة لضالة الغنم بعد مُضِي الوقت وتعريفها: هل الأوْلى يتصدّق بها، أم يأخذها ويأكلها؟","title":"حكم ضالة الغنم بعد مُضِي الوقت وتعريفِها","answer":"الجواب: لا، له، مُلْكٌ له لك أو لأخيك أو للذئب لكن بعد أن يعرّفها، يقول ﷺ: من آوى ضالّةً فهو ضال ما لم يعرفها رواه مسلم، يعرّفها سنة فإن شق عليه بقاؤها باعها، وحفظ ثمنها، وصفاتها، وإن تيسر أنها ترعى مع غنمه يخليها ترعى.\nس: لكن هل يقال: يتصدق بها، أم يمتلكها؟\n،الشيخ: لا مُلْكٌ له، إذا تمت السنة فهي مُلك له، حتى إذا جاء صاحبها يومًا من الدهر أدّاها إليه إذا عرّفها.","link":"https://binbaz.org.sa/fatwas/23525/حكم-ضالة-الغنم-بعد-مضي-الوقت-وتعريفها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ضالة الغنم بعد مضي الوقت، وتعريفها.mp3","categories":["اللقطة واللقيط"]},{"id":3362,"question":"تعريف السَّنة في جميع اللُّقَطة؟","title":"ما مدة تعريف كل لُقَطَةٍ؟ وأين يتم التعريف؟","answer":"الجواب: نعم لا بد من سَنة.\nس: ما عدا ما لا تتبعه هِمَّةُ أوْساط الناس؟\nالشيخ: الشيء الحقير لا، ما له شيء، مثل النبي قال: لولا أن تكون من الصدقة لأكلتها لما وجد تمرة في الطريق قال: لولا أن تكون من الصدقة لأكلتها دل على أن الشيء الحقير يُعفى عنه كالحبل، والتمرة، والتمرتين، والأشياء الحقيرة كالريال، والعشرة، والخمسة، في وقت ما لها قيمة.\nس: وبعد تعريفها سنة؟\nالشيخ: له، يملكها، فإن جاء صاحبها يومًا من الدهر، وعرّفها يعطيه إياها، ولو بعد سنتين.\nس: بالنسبة للتعريف لا بد في.....؟\nالشيخ: في مجامع الناس؛ حول المساجد، في الأسواق التي فيها يتجمع الناس: مَنْ له اللقطة؟ مَنْ له الدراهم؟ مَنْ له الشاة؟.\nس: ما تكفي الجرائد..؟\nالشيخ: لا، ما تكفي الجرائد، النداء في الأسواق أبلغ، ما الكل يقرأ الجرائد، وإن جُعل في الجرائد زُود ما يخالف، لكن لا بدّ من التعريف في مجامع الناس.\nس: وإذا تركها، إذا ترك ضالة الغنم؟\nالشيخ: ما عليه، لكن أخذها أفضل، النبي قال: خذها فإنما هي لك أو لأخيك أو للذئب، وإذا تركها ما بِدُّه يتكلف يتعب، لا بأس.\nس: إذا كانت تصل مثلًا إلى عشرة ريال، أو عشرين ريال؟\nالشيخ: هذه حقيرة، ما لها قيمة، ما تحتاج تعريف.","link":"https://binbaz.org.sa/fatwas/23528/ما-مدة-تعريف-كل-لقطة-واين-يتم-التعريف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تعريف الضالة سنة.mp3","categories":["اللقطة واللقيط"]},{"id":3780,"question":"ضالة الإبل؟","title":"ما حكم ضالة الإبل والغنم؟","answer":"الجواب: من الغلول، أخذها من الغلول: هي لك أو لأخيك أو للذئب إلا إذا كانت في مكانٍ عليها خطر؛ يأخذها ويُرسلها إلى الجهات المختصة التي تحفظها، إن كانت في محلٍّ فيه سُرَّاق يأخذونها ويأكلونها، أو في أرض مهلكةٍ، ما فيها رعي ولا ماء، ذكر العلماء أنَّ من المصلحة التي جاء بها الشرعُ أن يأخذها ويسلمها إلى ولاة الأمور إذا كانت لها جهة مختصة، وإلا يبيعها ويُسلِّمها للمحكمة إذا خاف عليها.  المقصود يُوصلها للجهة المختصة إن قدر، والجهة المختصة تعمل ما هو أصلح: من بيعها، أو جعلها مع رعاة الحكومة، يجعلها في وجهٍ يحفظها لأهلها، مع ضبط صفاتها...\nس: ضالة الغنم؟\nج: لا، هذه ضالة الغنم، لا يخليها، يأخذها، هي لأخيه أو للذئب، يأخذها ويُعرّفها سنةً، فإن عرفت وإلا فهي لك، ويضبط صفاتها وسِنّها، النبي ﷺ قال: مَن آوى ضالَّةً فهو ضالٌّ ما لم يعرفها، يأخذها ويُعرّفها سنةً كاملةً، وإذا كان ربيع وأمكن جعلها مع الغنم ترعى جعلها مع الغنم ترعى، وإن كان يخاف عليها يبيعها ويحفظ ثمنها ويُشهد على ذلك، وعلى صفاتها، ويُعرِّفها سنةً، فإن عرفت وإلا فهي له.","link":"https://binbaz.org.sa/fatwas/23977/ما-حكم-ضالة-الابل-والغنم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ضالة الإبل والغنم.mp3","categories":["اللقطة واللقيط"]},{"id":3948,"question":"يعني سَنَة يُعَرّفها؟","title":"ما مدة تعريف اللُّقَطة وأماكنها؟","answer":"الجواب: في مجامع الناس، من له الضالة؟ من له الشاة؟ من له العنز؟ من له الخروف؟ على حسب الحال.\nس: خارج المساجد؟\nالشيخ: في خارج المساجد نعم.\nس: هذا يعم في مكة والمدينة؟\nالشيخ: في كل مكان؛ لكن في مكة والمدينة لا تملك، يعرف دائمًا أو يضعها عند المسلمين، لا تملك. أما غير مكة والمدينة تملك بعد السنة.\nس: هل له أن يعرفها عن أبواب المساجد؟\nالشيخ: عند أبواب المساجد وفي مجامع الناس..\nس: إذا تصدق بقيمتها؟\nالشيخ: لا، لا يتصدق بقيمتها إلا بعد التعريف، لا بدّ يعرف سنة فإذا عرفها سنة وتصدق بعد ذلك فلا بأس، يتصدق، فإذا جاء ربها يغرمها له.\nس: ولو كانت شيئًا يسيرًا؟\nالشيخ: الشيء اليسير يُعفى عنه.","link":"https://binbaz.org.sa/fatwas/24171/ما-مدة-تعريف-اللقطة-واماكنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في تعريف الضالة سنة.mp3","categories":["اللقطة واللقيط"]},{"id":3949,"question":"إذا كانت من صغار الإبل؟","title":"حكم ضالة صغار الإبل","answer":"الجواب: إذا كان يخشى عليها من صغار السباع كالذئب فهي مثل الشاة يأخذها، يأخذها ويعرفها؛ قياسًا على الشاة؛ لأنها ضعيفة لا تتحمل البقاء.\nس: بعض الناس تسول له نفسه، يقول: بدل ما يأخذها غيري أنا آخذها؟\nالشيخ: المقصود إن أخذها بنية الأمانة جاز له، أما إن أخذها بنية الطمع فيها ما يجوز، إما يأخذها بنية الأمانة ويقوم بالواجب وإلا يتركها، لا يأخذها، إذا كان عنده ضعف، لابد أن يأخذها بقوة حتى يعرّفها، أو يخلّيها مكانها.","link":"https://binbaz.org.sa/fatwas/24172/حكم-ضالة-صغار-الابل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ضالة صغار الإبل.mp3","categories":["اللقطة واللقيط"]},{"id":4905,"question":"هل الغنم يعرَّف؟","title":"حكم أخذ ضالَّة الغنم ومدة تعريفها","answer":"سَنَة، من آوى ضالة -ضالة الحيوان يعني- فهو ضالٌّ ما لم يعرِّف، هذا يصدُق على الغنم بس. الإبل يدعها، والبقر والغنم والخيل والحُمُر.\nس:قوله: فهي لك أو لصاحبك أو للذئب؟\nج: يعني مع التعريف؛ لا تخلها يأكلها الذئب، خذها وعرفها.\nس: هل يأثم بعدم أخذ ضالة الغنم؛ خوفًا من المسؤولية؟\nج: لا ما يأثم، هي مباحة له، هي لك أو لأخيك أو للذئب، مباحة بشرط التعريف.","link":"https://binbaz.org.sa/fatwas/25420/حكم-اخذ-ضالة-الغنم-ومدة-تعريفها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تُعرف ضالة الغنم.mp3","categories":["اللقطة واللقيط"]},{"id":4906,"question":"يوجد في الأسواق أمانات هل يجوز للواحد يأخذ هذه اللقطة ويقول: أنا بأعرفها أم يعطيهم للأمانات وهم بدورهم يكون عندهم قسم للمفقودات؟","title":"ما كيفية التعريف بالضّالة ومعنى العفاص والوكاء؟","answer":"يعرفها أو يعطيهم إياها.\nس: يوجد لوحة في مؤخرة المسجد مكتوب عليها \"المفقودات\" يحط فيها مفتاح ضاع، يعني أشياء ثمينة ضاعت، توضع فيها، هل فيه بأس هذا؟\nج:  والله محتمل، من باب التعريف، لكن فيه إشارة لمصلحة المسلمين، يعني أن المفقودات في هذا المكان المعين، إن شاء الله ما فيه شيء؛ لأنه من التعريف.\nس: الإعلان في الجرائد هل يعتبر من التعريف؟\nج: الظاهر أنه من التعريف ولكن ما يكفي، وإلا هو زيادة تعريف إذا عرّف في الجرائد وعرّف في مجامع الناس من كمال النصح.\nس: معنى عفاصها؟\nج: العفاص هو الرباط.\nس: وكاءها؟\nج: الوكاء هو الرباط، ووعاؤها الخرقة التي فيها أو الكيس التي فيها أو الصندوق.\nس: والعفاص؟\nج: قال بعض أهل العلم: العفاص كيفية الربط، المقصود أنه يعتني بالشيء الذي يمنع الكذّابين من التحايل، يعني يحرص على صفات واضحة في الوكاء وفي الوعاء، وإن كان العفاص يعني كيفية العقد.\nالمقصود أنه يعتني بالأشياء التي يطمئن أن صاحبها إذا عرفها فهو صادق.","link":"https://binbaz.org.sa/fatwas/25421/ما-كيفية-التعريف-بالضالة-ومعنى-العفاص-والوكاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التعريف بالضّالة.mp3","categories":["اللقطة واللقيط"]},{"id":4907,"question":"إذا وجد مالًا في الطريق وسلّمه إلى جمعية خيرية بنية أن يتصدق عن هذا الشخص؟","title":"حكم مَن وجد مالًا وسلمه لجهة خيرية بنية الصدقة","answer":"لا، ما يصح، لا بدّ يعرّف وإلا يعطيها للمسؤول عن اللقطات؛ إن كانت جهة مسؤولة يعطيها إياها، وإلا يعرِّف اللقطة.\nس: الإشهاد واجب؟\nج: ظاهر الحديث الوجوب: فليشهد الأصل في الأوامر في الوجوب، لكن قد يقال: سكوته في أحاديث كثيرة يدل على الاستحباب؛ لأنه في حديث زيد بن خالد في الصحيحين وأحاديث أخرى كثيرة ما فيها الأمر الإشهاد، فقد يقال إن هذا يدل على أن المراد بالإشهاد الاستحباب والأفضلية.","link":"https://binbaz.org.sa/fatwas/25422/حكم-من-وجد-مالا-وسلمه-لجهة-خيرية-بنية-الصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجد مالاً في الطريق، وسلمه إلى جمعية خيرية بنية الصدقة.mp3","categories":["اللقطة واللقيط"]},{"id":4908,"question":"ألا يجب على الأمين أن يلتقط إذا خاف أن اللقطة تضيع؟","title":"هل يجب التقاط اللقطة إذا خُشي ضياعها؟","answer":"إذا وثق بنفسه لا بأس، إذا اطمأن أنه سوف يقوم باللازم، وإلا يتركها ويستريح.\nس: ما يجب؟\nج: ما يجب، لها تبعية.\nس: إذا كان يخشى أن يلتقطها الخائن؟\nج: ما يلزم، إن وثق بنفسه وأراد الإحسان يلتقطها، أما أنه يجب: ما يلزم.","link":"https://binbaz.org.sa/fatwas/25423/هل-يجب-التقاط-اللقطة-اذا-خشي-ضياعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجب على الأمين التقاط اللقطة.mp3","categories":["اللقطة واللقيط"]},{"id":4909,"question":"إن التقط بنية التعريف ثم تلفَتْ هل يضمن؟","title":"حكم من التقط لقطة بنية التعريف ثم تلفتْ عنده؟","answer":"إن كان بتفريط يضمن، وإن كان بدون تفريط ما يضمن. أو تعدى.\nس: لو كان طعامًا بالحرم، وخشى أن يتلف؟\nج: يبيعه ويحفظ الثمن، يحفظ صفاته ويبيعه، أو يخشى من الفساد أو غيره، يخشى تلفه فيبيعه ويحفظ ثمنه، أو لباس.\nس: ولا يجب عليه الالتقاط في هذه الحالة حتى إذا كان يخشى الفساد؟\nج: لا يجب عليه.\nس: حتى لو خشي عليه الفساد؟\nج: ما قال النبيُّ ﷺ: فليأخذها، إنما بيَّن أنَّ عليه كذا وكذا، عليه إذا أخذها كذا وكذا، وإلا ما هو بلازمٍ أن يجبر نفسه.","link":"https://binbaz.org.sa/fatwas/25424/حكم-من-التقط-لقطة-بنية-التعريف-ثم-تلفت-عنده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من التقط لقطة بنية التعريف ثم تلفت، فهل يضمن.mp3","categories":["اللقطة واللقيط"]},{"id":5302,"question":"هل يجوز أن تُلقط اللقطة في مِنى ومزدلفة وعرفات أثناء الحج؟","title":"ما حكم اللقطة في مِنى وعرفات أثناء الحج؟","answer":"الجواب: النبي نهى عن لُقطة الحاج، فإذا وجد اللقطة في الحرم عَرَّفها أبدًا ولا تُملك، إلا إذا كانت خارج الحرم في عرفات في الطريق فالأحوط أيضًا أن يعرِّفها دائمًا أو يعطيها اللجنة؛ لأن في بعض الأحاديث الصحيحة الرسول نهى عن لقطة الحاج، فهذا يعم لقطة الحاج في الحرم وفي غير الحرم، فينبغي أن يعرِّفها دائمًا أو يعطيها المحكمة حتى يأتي صاحبها.[1]","link":"https://binbaz.org.sa/fatwas/30952/ما-حكم-اللقطة-في-منى-وعرفات-اثناء-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 022.mp3","categories":["اللقطة واللقيط"]},{"id":5686,"question":"ما حد قطيعة الرحم؟ أعني ما هي المدة التي إذا مرت دون زيارتهم كانت قطيعة رحم؟","title":"كيف تكون صلة الرحم؟ وما هو حد القطيعة؟","answer":"الجواب: ما في حد محدود، صلة الرحم بالكلام الطيب، ومواساة الفقير منهم، ورد السلام عليهم، وبداءتهم بالسلام، وإعانتهم على الخير، كل هذا من صلة الرحم. وقطيعة الرحم ما لها حد محدود، جفاؤهم الذي يعد خلاف المعتاد نوع من القطيعة، جفاؤهم من غير موجب شرعي، وعدم الإنفاق على فقيرهم، والإحسان إليه، وعدم الشفاعة لمظلومهم حتى ينصر في مظلمته، ونحو ذلك، قد يعد من القطيعة.  فالقطيعة أمر عرفي، والصلة أمر عرفي، فما هو معروف بين المسلمين الصلة، والإحسان، والاتصال، والسلام، وبذل المعروف يعد صلة، وما كان بين المسلمين يعد جفاء، ويعد قطيعة، فكذلك. وليس الواصل بالمكافئ؛ لأن بعض الناس إذا ما وصله أقاربه فهو لا يصلهم يقول: لا يصلونني، ولا يجوني، ما أنا بواصلهم فهذا غلط، النبي -عليه الصلاة والسلام- يقول: ليس الواصل بالمكافئ، وإنما الواصل الذي إذا قطعت رحمه وصلها هذا الواصل.  وكذلك يقول ﷺ لما قال له رجل: يا رسول الله، إن لي قرابة أصلهم، ويقطعونني، وأحلم عليهم، ويجهلون عليّ، وأحسن إليهم، ويسيئون إليّ، قال: لئن كنت كما قلت لكأنما تسفهم المل، ولا يزال معك من الله عليهم ظهير ما دمت على ذلك فالله -جل وعلا- يعينه عليهم ما دام على حاله الطيبة، ويكون بهذا هو الواصل وهم القاطعون. أما إن وصلوك وصلتهم، وإن قطعوك قطعتهم لا، هذا ليس بصلة، حتى الأجنبي إذا وصلك تصله، الأجنبي الذي ما هو بقريب إذا وصلك وأحسن إليك، عليك المقابلة، والمكافأة، لكن الرحم، والقرابة لها حق وزيادة على هذا تصلهم، وإن قطعوا، وتحسن إليهم، ترد عليهم السلام، تبدأهم بالسلام، تدعوهم للوليمة تجيب دعوتهم.  ولو قطعوك لأجل وحشة بينك وبينهم، أو شحناء، أو خصومات لا تقطعهم أنت، لكن لك أن تهجرهم ثلاثة أيام عند الوحشة، والنزاع، والخصومات لأجل حظ الدنيا، لك أن تهجرهم ثلاثة أيام فقط، لا يزيد على ذلك؛ لأن النبي ﷺ قال: لا هجرة فوق ثلاث.  فالواجب أنه يصله بعد الثلاث، ويعود على حاله الأولى بعد الثلاث، ولا يهجر فوق ثلاث، وخيرهما الذي يبدأ بالسلام، خير المتهاجرين الذي يبدأ بالسلام.","link":"https://binbaz.org.sa/fatwas/994/كيف-تكون-صلة-الرحم-وما-هو-حد-القطيعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_23.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق المحمودة"]},{"id":5747,"question":"عثرت على رأسين من الغنم ضائعة، وقد سألت عن صاحبها في عدة أماكن، وفي سوق الغنم، ولم أجد لها صاحب، فأرجو إفتائي بما أصنع بها؟","title":"ما يفعل من وجد ضالة الغنم؟","answer":"الجواب: إذا وجد الإنسان رؤوسًا من الغنم، أو غير الغنم كالبقر، وغيرها مما يخشى عليه الذهاب والضياع يعرفه سنة كاملة، فإن عُرف فالحمد لله، وإن لم يُعرف أحل له ... ... النبي -عليه الصلاة والسلام- قال: من آوى ضالًا فهو ضال فعليه أن يعرفها ... أما البقر والإبل فهذه تحمي نفسها، فلا حاجة إلى أن يتولاها ويقبضها، بل يتركها في الصحراء حتى يجدها أهلها، وإذا كانت في الأسواق سوف يجدها أهلها.  أما الغنم فينبغي له أن يعرفها سنة كاملة، وهكذا من كان من جنس الغنم من الحيوانات الصغيرة التي يخشى عليها الموت .. أو نحو ذلك فإنه يعرفها أيضًا. فالحاصل: أنه يعرفها سنة كاملة، فإن عرفت وإلا فهي له، والأجرة على الصحيح تكون عليه، الأجرة ينادي عليها، ويعرفها في الناس تكون عليه من هذا المال الذي وجده، وإن تركه ولم يأخذه فلا بأس.","link":"https://binbaz.org.sa/fatwas/1066/ما-يفعل-من-وجد-ضالة-الغنم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_80.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق المحمودة"]},{"id":5756,"question":"ذهبت للحج مع أبي، ووجدت نقودًا مقدارها ألفان ومائتان وخمسون ريالًا سعوديًا عند الجمرة الوسطى، وأبي تبرع بها لمسجده فما حكم ذلك؟","title":"حكم لُقَطة مكة","answer":"الجواب: الواجب على من وجد لقطة في الحرم لا يتبرع بها للمسجد، ولا لغير المسجد؛ بل يعرفها دائمًا في الحرم، من له الدراهم؟ من له الذهب؟ من له كذا؟ دائمًا. النبي -عليه الصلاة والسلام- قال:  ولا تحل ساقطتها إلا لمعرف فلا تصرف في كذا، ولا في  كذا، بل ينادى عليها حتى يأتي أهلها، وإذا كان لا يستطيع ... في مكة، والهيئة معدة لهذا الشيء، وتبرأ ذمته حتى يأتي أهلها يسألون عنها. أما أنها تصرف في فقير أو في مزرعة أو في مسجد أو كذا لا ما يجوز، الرسول -عليه الصلاة والسلام- قال: ولا تحل ساقطتها إلا لمعرف وفي رواية : إلا لمنشد ينادي عليها: من له الذهب من له إلى آخره، وهكذا ... المدينة. السؤال: ولو تركها يا شيخ؟ الجواب: إن تركها فلا بأس .......","link":"https://binbaz.org.sa/fatwas/1067/حكم-لقطة-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_81.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق"]},{"id":5774,"question":"ذهبت للحج مع أبي، ووجدت نقودًا مقدارها ألفان ومائتان وخمسون ريالًا سعوديًا عند الجمرة الوسطى، وأبي تبرع بها لمسجده فما حكم ذلك؟","title":"حكم لُقَطة مكة","answer":"الجواب: الواجب على من وجد لقطة في الحرم لا يتبرع بها للمسجد، ولا لغير المسجد؛ بل يعرفها دائمًا في الحرم، من له الدراهم؟ من له الذهب؟ من له كذا؟ دائمًا. النبي -عليه الصلاة والسلام- قال:  ولا تحل ساقطتها إلا لمعرف فلا تصرف في كذا، ولا في  كذا، بل ينادى عليها حتى يأتي أهلها، وإذا كان لا يستطيع ... في مكة، والهيئة معدة لهذا الشيء، وتبرأ ذمته حتى يأتي أهلها يسألون عنها. أما أنها تصرف في فقير أو في مزرعة أو في مسجد أو كذا لا ما يجوز، الرسول -عليه الصلاة والسلام- قال: ولا تحل ساقطتها إلا لمعرف وفي رواية : إلا لمنشد ينادي عليها: من له الذهب من له إلى آخره، وهكذا ... المدينة. السؤال: ولو تركها يا شيخ؟ الجواب: إن تركها فلا بأس .......","link":"https://binbaz.org.sa/fatwas/1067/حكم-لقطة-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_81.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق"]},{"id":5848,"question":"رجل ماشي في الشارع، وتحصل على صنجل وأخذه، وهو لا يعلم ما هو، وبعد أن وصل عنده أهله في بلاد بعيدة أعطاه أهله، وتبين أنه ذهب، وجلس محتارًا كيف يصنع؟ ولم يقدر الآن، وله مدة ست، أو سبع سنوات، أو أكثر، فهل يجزئ عليه أن يدعو لصاحبه، ويستغفر له مع أنه لا يعلم من هو أفتوني؟","title":"حكم اللقطة","answer":"الجواب:  هذا الذي وجد الصنجل أظنه صنجل الساعة، إذا كان ذهبًا له أهمية؛ فهذا الواجب تعريفه، يعرفه سنة كاملة لعله يعرف، والآن أخره كثيرًا؛ فالواجب أن يعرفه إذا كان له قيمة، يعرفه في البلد التي وجدها فيها، من له صنجل الساعة الذي ضاع في كذا وكذا، سنة كذا وكذا؟ إن وجد أحدًا يعرفه بصفاته الخاصة؛ أعطاه إياه، وإن لم يوجد من يعرفه؛ تصدق به؛ لأنه قصر في تعريفه، ولم يعرفه في وقته، تصدق به على بعض الفقراء. أما إن كان الصنجل ما يسوى شيئًا، يسوى خمسين ريالًا، أو أربعين ريالًا، فهذا أمره سهل إن أكله؛ فلا بأس، وإن تصدق به؛ فلا بأس؛ لأنه ما يتحمل التعريف، لو أعطى واحدًا يعرفه أكل أجرته. فالحاصل: أن الشيء القليل يعفى عنه، عشرة ريالات، أو عشرين ريالًا، فهذه لا تتبعها النفوس اليوم، النفوس في أوساط؛ لأن المال كثر بين الناس، فالشيء القليل لا يتحمل التعريف، لكن إذا كان شيئًا له أهمية، يعرف سنة كاملة؛ فإن عرف وإلا فهو للذي وجده، كما قاله النبي -عليه الصلاة والسلام- يعرف في مجامع الناس، في الشهر مرتين، ثلاث، أربع عند اجتماع الناس، وعند خروجهم من الجمعة، وموضع السوق، إن كتب في الجريدة، أو أذيع في التلفاز، أو في الإذاعة؛ فهذا طيب أيضًا إذا تيسر ذلك. السؤال: سؤال آخر: أحد أصحاب السيارات وجد بطانية في سيارته، ولا يعرف صاحبها، ودارت سنة؟ الجواب: مثل هذا البطانية في السيارة مثل اللقطة، هذه من الركاب الذين ضيعوها، البطانية إن كان لها قيمة إن كان لها أهمية؛ تعرف سنة، إذا كانت تسوى شيئضا كثيرًا 200 ريال 300 ريال لها  أهمية أو 100 ريال على الأقل؛ لا بأس يعرفها سنة، فإن عرفت وإلا فهي له، من له البطانية التي نسيها في بعض السيارات؟ في البلد التي هو فيها، أو ما يقاربها في مجامع الناس سنة كاملة، فإن عرفت، وإلا فهي له، وإن كانت حقيرة ما تساوي شيئًا؛ فأمرها سهل إن استعملها؛ فلا بأس، وإن تصدق بها؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/1182/حكم-اللقطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_178.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق"]},{"id":6276,"question":"يوجد لدي بهيمة ضالة، عنزة لها أكثر من خمسة عشر يومًا، قد بحثت عن صاحبها، ولم أجده، أرجو الحكم في التصرف فيها؟","title":"كيفية التصرف مع ضالة الغنم","answer":"الجواب:  عرفها دائمًا، عرفها حتى تتم السنة، عرفها سنة كاملة في مجامع الناس، في الشهر مرتين، ثلاثًا، أربعًا، من له الضالة؟ من له العنز الضالة؟ من له العنز الضالة؟ وإذا كملت السنة، ولم يأت إليها أحد؛ فهي لك، وإذا كنت يشق عليك علفها؛ بعها، واحفظ ثمنها، واحفظ صفاتها عندك، فإذا جاء ربها، وعرفها؛ فأعطه الثمن، وإن لم يأت أحد مع التعريف؛ فهي لك، لكن لا تسكت، عرفها سنة كاملة في مجامع الناس، في كل شهر ثلاث مرات أربع مرات، أكثر، من له الضالة؟ من له الضالة؟ .. السؤال: حديث الرسول: هي لك أو لأخيك أو للذئب؟ الجواب: الرسول -عليه الصلاة والسلام- قال: من آوى ضالة؛ فهو ضال من لم يعرفها، رواه مسلم، وقوله: هي لك، أو لأخيك، أو للذئب يعني لا تدعها، خذها، ولكن لا يأخذها حتى يعرفها.  السؤال: ولو تركها يا شيخ؟ الجواب: إذا تركها ما عليه شيء.","link":"https://binbaz.org.sa/fatwas/1784/كيفية-التصرف-مع-ضالة-الغنم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_623.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق المحمودة"]},{"id":6843,"question":"شخص وجد بنتًا صغيرة لقيطة، عاشت عنده حتى الآن، وأنه ضمها في تابعيته، وأعطى لها اسمه، ما حكم علاقة البنت به شرعًا، وهل تستمر تسمية البنت بلقب العائلة، وهل يخبر البنت عند زواجها أنه ليس أبوها الحقيقي؟","title":"حكم تبني اللقيطة","answer":"الجواب: نعم، لا بد من هذا، تنسب إليهم؛ لأنهم أولياؤها، ربوها، وأحسنوا إليها، ولكن لا تكون بنتًا له، ينسبها إلى غيره، بنت عبدالله، بنت عبدالرحمن، الناس كلهم عباد الله، عبدالله، عبدالرحمن، عبداللطيف، ولا ينسبها إليه؛ لأنها لو نسبها إليه قد يظن أنها بنت له؛ فترث مع أولاده، وتصير محرمًا لهم، لا هذا لا يجوز، هذا فيه خطر عظيم.  أما كونه أحسن إليها، ورباها هذا له أجر في ذلك، لكن إذا كان ما رضعت من زوجته، ولا من بناته، ولا من أخواته، له زواجها، أجنبية يعتبرها، ولأولاده أن يتزوجوها، أما إذا كانت زوجته أرضعتها؛ لأنها كانت صغيرة قبل الفطام، يعني فأرضعتها زوجته، يكون أبًا لها، أو أرضعته بنته؛ يكون جدًا لها، أو أرضعته أخته؛ يكون خالًا لها.","link":"https://binbaz.org.sa/fatwas/2709/حكم-تبني-اللقيطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1208.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق"]},{"id":6883,"question":"ما رأيكم إذا وجد الإنسان شاة، أو ناقة بأرض خلاء، وتولدت حتى كثرت؟ هل تحل للذي حفظها، وأسقاها، ورعاها، أم تحرم عليه؟ وهل يجب كفارة إذا أكل شيئًا منها؟","title":"حكم لقطة الغنم والإبل","answer":"الجواب: إذا وجد الإنسان شاة من الضأن، أو من المعز في مكان يخشى عليها منه؛ لأنها ليست قريبة من السكن من أهل السكان، ومن أهل الأغنام، ونحو ذلك؛فإن هذه تسمى لقطة، فإذا أخذها، وعرفها سنة في مجامع الناس، وفي مظان معرفتها، ولم يعرفها أحد؛ فإنها تكون له تكون من عرض ماله، ويتصرف فيها كسائر ماله بعد السنة، لكن يحفظ صفاتها، وعلاماتها؛ حتى إذا جاء طالبها يومًا من الدهر؛ أداها إليه، أو أدى قيمتها إن كانت مفقودة، هذا هو الواجب عليه في جميع اللقطات، أن يعرفها سنة كاملة في مجامع الناس، في كل شهر مرتين، ثلاث، أربع، على حسب ما تيسر، فإن عرفت .. فالحمد لله، وإلا استعملها كسائر ماله. وإذا كان بقاؤها في يده قد يضره، ويضر صاحبها؛ باعها، وحفظ ثمنها، وصفاتها حتى يجد ربها، وإذا كان في قرب المحاكم، والبلاد .. المحكمة، وضبطها عند المحكمة، وإن شاء جعلها عند المحكمة حتى تحفظ عندها، فإذا جاء ربها؛ سلمت له، وإن شاء حفظها عنده حتى تمر السنة، فإذا مرت السنة، ولم يجد أحدًا لها؛ فهي كسائر ماله، سواء بنفسها، أو قيمتها. أما الإبل فإنها لا تلتقط، النبي ﷺ قال: إن معها سقاءها، وحذاءها، ترد الماء، وتأكل الشجر، حتى يلقاها ربها ونهى عن التقاطها، فلا تلتقط، اللهم إلا أن تكون في محل مسبعة، يعني: على خطر من أن تتلف للسباع التي في الأرض، فحينئذ يسوقها إلى الأرض السليمة، حتى تبتعد عن الخطر، ويكون مأجورًا في ذلك، وأما أن يأخذها فلا؛ لأن الرسول ﷺ نهى عن التقاط الإبل، وقال: إن معها سقاءها، وحذاءها، ترد الماء، وتأكل الشجر، حتى يلقاها ربها. \n\nالسؤال: باقي السؤال: إذا وجد ناقة، لا يعرف صاحبها، ثم حلبها، وشرب لبنها، هل يوجد كفارة لذلك؟ الجواب: إذا وجدها في البر، وشرب منها؛ لا يضره -إن شاء الله- ولا حرج عليه في ذلك.","link":"https://binbaz.org.sa/fatwas/2764/حكم-لقطة-الغنم-والابل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1256.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق"]},{"id":6889,"question":"إذا كنت أنا صاحب إبل، وجاءتني ناقة من الإبل، ولكن طردتها، ولم تذهب عن إبلي، وبالتالي استعملتها مثل الركوب، والظعن عليها حتى تلفت؟","title":"حكم من استعمل ضالة الإبل حتى تلفت","answer":"الجواب: هذا لا يجوز لك، ولو جاءت إلى إبلك عليك أن تطردها، أو تسلمها لولي الأمر، الأمير في بلدك، أو قاضي المحكمة، حتى تسلم من شرها، فإذا استعملتها؛ ضمنتها، وعليك غرامتها لصاحبها، أو لبيت المال حتى تصرف في وجوه الخير، لأنك قد عصيت ربك في إيوائها، وركوبها، واستعمالها.","link":"https://binbaz.org.sa/fatwas/2776/حكم-من-استعمل-ضالة-الابل-حتى-تلفت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1268.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق"]},{"id":7581,"question":"هذه الرسالة وردت من القصيم من عيون الجوى من المرسل (ب. س. ص) يسأل عن الضالة في الحرم، يقول: منذ ثلاث سنوات حججت، وأثناء السعي وجدت خمسين ريال فأخذتها في المسعى، وبعد الانتهاء من السعي اشتريت بها ماءً داخل الحرم ووزعته على بعض الناس وشربت أنا منه، وقلت: اللهم اجعل أجره وثوابه لصاحب الفلوس، هل أنا آثم في عملي هذا أم لا، وهل الماء الذي شربته حرام، وما هو الحل إذا أنني أخطأت في عملي هذا، علماً بأن الخمسين ريال هذه سوف تذهب هباءً من دوس أرجل الناس عليها، ولكم جزيل الشكر؟","title":"حكم لقطة الحرم","answer":"الجواب: لقطة الحرم -مكة المكرمة- لا يجوز أخذها إلا لمن يعرفها؛ لأن الرسول ﷺ قال: ولا تحل ساقطتها إلا لمنشد، يعني: معرف. ساقطة مكة، ما يكون في الحرم من اللقطات والضوال لا يجوز التقاطه إلا لمن يعرفه، دائماً دائماً، لعله يجده صاحبه في مجيئه إلى مكة في الحج والعمرة، فإن لم يعرفه فليضعه عند موكلين بهذه الأمور، من جهة المحكمة أو من يقوم مقام المحكمة في حفظ اللقطات في الحرم، ولا يأخذه للتملك بالتعريف ولا لغير ذلك، بل الواجب على المسلم إذا رأى لقطة في الحرم من دراهم أو أمتعة أو شبه ذلك مما له مالية أنه يعرفه، يلتقطه ويعرفه، أو يتركه في مكانه يأخذه غيره، فإن لم يعرفه وجب أن يسلمه للمسئولين في الحرم عن اللقطات، إلا إذا كان الملتقط شيئاً قليلاً حقيراً فلا حرج، مثل الخمسين ريال وأشباهها، هذه اليوم تعتبر حقيرة في مثل البلاد السعودية، تعتبر لقطة حقيرة، ثم لو تركها لديست وأتلفت، فهذه اللقطة إذا أكلها أو تصدق بها، أو جعلها في ماء زمزم ووزعها على الناس، كل ذلك لا بأس به كله طيب؛ لأنها حقيرة وقليلة، فإن أكلها فلا بأس، وإن تصدق بها فلا بأس، وإن جعلها في ماء زمزم ووزعه على الناس فلا بأس، كل هذا إن شاء الله طيب ولا حرج فيه، والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/4587/حكم-لقطة-الحرم ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_018/01805.mp3","categories":["اللقطة واللقيط"]},{"id":7679,"question":"هذا يسأل عن اللقطة يقول: لقد قمت بأداء فريضة الحج، وأديت مناسكها كاملةً، ولكن عندما ذهبت لكي أتغسل لكي أقوم بطواف الوداع وجدت في المغسل مبلغاً من النقود الكويتية، وأنا حالتي يعلمها الله من الفقر، فأخذت النقود وطفت طواف الوداع وذهبت إلى أهلي ولم يعلم أحد، وأنا الآن بخير وغني وأرجو أن أتصرف ولا أدري ماذا أفعل أرشدوني أرشدكم الله المقدم (م. س. ع)؟","title":"حكم لقطة مكة","answer":"الجواب: إن كان يعرف أهلها أرسلها إليهم واستباحهم واستحلهم، وإن كنت أيها السائل لا تعرف أهلها فإن عليك أن تتصدق بها على الفقراء والمساكين بالنية عن صاحبها، والله يغفر لنا ولك مع التوبة والإنابة إلى الله سبحانه وتعالى وعدم العودة إلى مثل ذلك، كان الواجب عليك أن تعرفها ذاك الوقت، وتنادي عليها: من له النقود.. من له النقود.. من له النقود؟ ثم إذا لم تجدها سلمتها للمسئولين بمكة عن اللقطات، أما الآن وقد طال الأمد فعليك أن تتصدق بها عن صاحبها مع التوبة والاستغفار، وصاحبها ينتفع بها، ويؤجر عليها، ولا شك أن هذا هو الطريق الآن إلى براءة ذمتك. نعم.\nالملقي: أحسنتم أثابكم الله.","link":"https://binbaz.org.sa/fatwas/4881/حكم-لقطة-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_040/04009.mp3","categories":["اللقطة واللقيط"]},{"id":7769,"question":"هذه رسالة من سعيد صالح الزهراني من أبها، يقول: عندي واحد من جماعتي ضاعت له غنم، وقصدنا بلد بعيد، فقال: إن وجدتم غنمي فهاتوا بها معكم، فوجدنا رجل تهامي عنده ثلاث غنم ضائعة، وعليها وسم صاحبي، فطلبتها منه فقال: أنا خسرت عليها رعاية وشعير، فأعطيته مائة ريال، فلما جبتها لصاحبي قال: ما هي غنمي، والآن لا أستطيع وجود التهامي ولا صاحبها، فكيف أعمل بها؟ وفقكم الله.","title":"حكم ضالة الغنم","answer":"الجواب: الذي يجب في مثل هذا أنه ينادي عليها.. يعرفها سنة كاملة؛ لأنها في حكم اللقطة؛ لأن صاحبها أخبر أنها لقطة، فيعرفها هو، وينادي عليها في مجامع الناس: من له غنم؟ من له غنم؟ ويعرف صفاتها ويحفظها، وإذا خاف عليها من النفقة يبيعها، ويحفظ الصفات والثمن، وينادي سنة كاملة، فإن وجد أهلها وإلا فهي له، الثمن له، وإن تصدق بذلك إذا لم يجد أهلها، فهذا لا بأس به.\nالمقصود أن حكمها حكم اللقطة يعرفها، لقول النبي ﷺ: من آوى ضالة فهو ضال ما لم يعرفها، وهذه ضالة، والنبي عليه السلام قال: من آوى ضالة فهو ضال ما لم يعرفها، رواه مسلم ، فهذا عليه التعريف، والتعريف أن ينادي عليها في مجامع الناس في الشهر مرتين.. ثلاث.. أربع، يقول: من له الغنم الضائعة؟ فإذا جاءه من يعرف صفاتها وأماراتها الخفية دفعها إليه، أو جاءه يقيم البينة عليها دفعها إليه، فإن مضت سنة ولم تعرف فهي له، سبيلها سبيل ماله، كما جاء في الحديث، وإن تصدق بها ولم يعني تطب نفسه بقبولها فلا بأس. نعم.\nالمقدم: طيب، لو تصدق بها وبعد سنتين جاء صاحبها؟\nالشيخ: يخير صاحبها، إن شاء صارت الصدقة له، وإن شاء دفع له القيمة التي تساويها، وإن قبل الصدقة فالحمد لله.\nالمقدم: وتكون الصدقة للأول لو أخذ ..\nالشيخ: الأجر، نعم؛ لأن النبي عليه السلام قال في بعض الأحاديث: متى جاء صاحبها يوماً من الدهر فأدها إليه.\nالمقدم: طيب لو مثلاً مكثت عنده ولم يبعها وأنجبت مثلاً غنم أخرى؟\nالشيخ: كلها له، بعد مدة بعد السنة.\nالمقدم: نعم.\nالشيخ: إذا أنجبت بعد السنة فهو له، وليس لصاحبها إلا الأصول؛ لأنها صارت ملكاً له بعد تعريفه. نعم.","link":"https://binbaz.org.sa/fatwas/4976/حكم-ضالة-الغنم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_046/04601.mp3","categories":["اللقطة واللقيط"]},{"id":7901,"question":"أيضاً لديه سؤال عن اللقيط، يقول: إذا وجد إنسان طفلاً لقيط مرمياً عند أحد أبواب المساجد وأراد أن يأخذه ويربيه، فماذا يسميه؟ ولمن ينسبه حيث أنه في يوم من الأيام سوف يدخل المدرسة ويحمل حفيظة النفوس؟","title":"تسمية الطفل اللقيط","answer":"الجواب: يكون قد أحسن في هذا إذا رباه وأحسن إليه يكون قد أحسن، ويسميه بالأسماء الشرعية مثل: عبد الله بن عبد الله، عبد الله بن عبد اللطيف، عبد الله بن عبد الكريم، كل الناس عباد الله، حتى لا يحصل عليه مضرة في المدارس وحتى -يعني- لا يصيبه نقص وانكماش وضرر.\nفالمقصود: أن يسميه من الأسماء المعبدة: عبد الله بن عبد الكريم، عبد الله بن عبد اللطيف، عبد الله بن عبد الملك، وما أشبه ذلك، نعم، هذا هو أقرب إن شاء الله.\nأو يسميه باسم يصلح للنساء والرجال، وقد يكون هذا أسلم أيضاً؛ لأنه ينسب إلى أمه، فإذا سماه اسماً يصلح للرجال والنساء كأن يقول: عبد الله بن عطية، ابن عطية الله، عبد الله بن هبة الله؛ لأن هبة الله وعطية الله تصلح للنساء والرجال، والمعنى: ابن أمه، هبة الله يعني: أمه، يعني: من هبة الله، عبد الله بن عطية، عبد الله بن هبة الله، عبد الله بن كذا، بأسماء تصلح للنساء والرجال، نعم، هذا يكون أسلم.\nالمقدم: ويسميه اسم ثلاثي وكلهم عبد؟\nالشيخ: ما فيه بأس، أو مثل عبد الله بن هبة الله بن عطية الله، أو عبد الله بن عطية بن هبة الله، ويكون مراده أمه وجدته، نعم، ما فيه بأس، كل واحد يقال له: هبة الله، يقال: عطية الله، يقال لها مثلاً، يأتي باسم يصلح غير هذه الأسماء يصلح للنساء والرجال لا بأس. نعم .","link":"https://binbaz.org.sa/fatwas/5384/تسمية-الطفل-اللقيط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_061/06103.mp3","categories":["اللقطة واللقيط"]},{"id":7999,"question":"هذه الرسالة عن اللقطة بعث بها المستمع صالح أحمد عسكر ، يقول: أرجو أن تعرض رسالتي هذه على فضيلة الشيخ عبد العزيز ، والسؤال هو: إذا وجد الشخص حاجة ملقاة على الطريق، فهل يحق له أن يأخذها أم لا؟","title":"من وجد شيئًا ملقى هل يلتقطه أم يرتكه؟","answer":"الجواب: إذا كان يثق من نفسه أنه يعرفها ويؤدي الواجب يأخذها، وإلا فليدعها؛ لأن الواجب عليه أن يعرفها سنة كاملة، ينادي عليها في الأسواق التي يجتمع الناس، عند أبواب الجوامع، وأشباهها من مجامع الناس يقول: من له الذاهبة، من له الذاهبة، من له البشت من له الشنطة، من له كذا من له كذا؟ ولا يبين صفاتها، لكن يشير إلى حقيقتها ولا يبين صفاتها، فإذا جاء من يعرفها بصفاتها أعطاه إياه، فإن مضت سنة ولم يأت أحد فهي له، هكذا أمر النبي ﷺ من وجد لقطة فليعرفها بعد أن يعرف عفاصها ووكاءها وعددها إن كانت نقود.\nالمقصود بعد أن يعرفها نقود أو غير نقود، بعد أن يعرف الحقيقة والأوصاف التي ينبغي أن تحفظ، فإذا أتقنها كتبها عنده، وضبطها وعرفها سنة كاملة، ينادي في مجامع الناس في الشهر مرتين ثلاث أكثر من له الذاهبة؟ من له اللقطة التي هي كذا وكذا؟ هي مثلاً شنطة مثلاً بشت مثلاً سيف، مثلاً خنجر، مثلاً كذا، ثم إذا جاء الذي يلتمسها يبين صفاتها ما هي صفاتها، وايش كذا، فإذا وصفها بصفاتها المطابقة أعطاه تلك اللقطة، وإن مضت السنة ولم يأت أحد فهي كسائر ماله، ينتفع بها كسائر ماله، فإذا جاء صاحبها يوم من الدهر وعرف صفاتها أعطاها إياه. نعم.","link":"https://binbaz.org.sa/fatwas/5565/من-وجد-شيىا-ملقى-هل-يلتقطه-ام-يرتكه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_074/07407.mp3","categories":["اللقطة واللقيط"]},{"id":8097,"question":"هذه رسالة وردتنا موجهة لفضيلتكم، يقول: فضيلة الشيخ عبد العزيز بن عبد الله بن باز السلام عليكم ورحمة الله، وبعديقول: أفيدكم بأنني أشتغل في بقالة في المدينة المنورة، وعند البقالة قمامة، وفي ذات ليلة في شهر رمضان المبارك بعد التراويح وقفت سيارتي عند القمامة، وبعد نزلت من السيارة، وجدت في القمامة مسجل وراديو ناشيونال، والبقالة ليس عندها مواقف، هي الوحيدة، والمسجل جديد وعليه اسم راعيه، وأنا نفسي طيبة منه، لا أريده أبدًا، أفيدوني جزاكم الله عن هذا، وما أصنع به؟","title":"حكم لقطة الراديو والمسجل","answer":"الجواب: الذي نرى أن صاحبه يلتمس ويعطى هذا الراديو؛ لأن هذا في الغالب ما يطرح في القمامة، فلعله طرحه صبي صغير، أو طرحه غير عاقل، فمثل هذا يلتمس، ما دام اسمه عليه يلتمس ويعطى صاحبه، فإن لم يعرف هو من اللقطات، لقطة ينادى عليه إذا كان لها قيمة، يسوى قيمة مايتين ثلاثمائة أربعمائة هذا يكون من اللقطات، أيش الثاني:  الراديو؟ المقدم: مسجل. الشيخ: والمسجل كذلك إذا كان لها قيمة وسليم، له قيمة كبيرة ينادى عليه، وإن كان عليه اسم صاحبه فيعطى صاحبه، ولا يعتبر هذا من القمامة التي يأخذها من شاء ؛ لأن الظاهر إن هذا لم يلق في القمامة، إما إنه تصرف صبي صغير ألقاه، وإما من خادمة لا تعقل، يعني ضعيفة التصرف كالمجنونة، فمثل هذا ما يلقيه عاقل في القمامة، لا مسجل ولا راديو، فإذا كان اسم صاحبه عليه يلتمس ويعطى إياه. المقدم: فضيلة الشيخ أعتقد أنه لما كان في ليالي رمضان، وخاصة كما أشار بعد التراويح، ربما أنه سمع بعض محدثي المساجد، وحديثه مثلاً عن آلات الملاهي وكذا، فرغب عن هذا المسجل وعن .... فرماه؟ الشيخ: هو محتمل نوع احتمال، أقول: نوع احتمال قد يكون ما هو بعيد، قد يكون رماه لكن إذا كان اسمه عليه وأعطاه إياه يكون أحوط من باب الاحتياط، وإن لم يجده وباعه وتصدق به فحسن. نعم.","link":"https://binbaz.org.sa/fatwas/5887/حكم-لقطة-الراديو-والمسجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_086/08603.mp3","categories":["اللقطة واللقيط"]},{"id":8187,"question":"هذه رسالة وردتنا من العراق، يقول مرسلها أحمد عبد الله حمد الشلال من محافظة نينوى ناحية.. إلى آخره، يقول: إني في سنة ألف وتسعمائة وأربعة وسبعين قمت بحج بيت الله الحرام، وعندما انتهت فترة الحج سافرنا إلى أهلنا، وعندما خرجنا من الكويت إلى العراق تبرعنا نحن الحجاج لسائق السيارة التي جئنا فيها إلى بيت الله الحرام بمبلغ كل حاج اثنان دينار، وجمعتها أنا، وبقيت فلوس لبعض الحجاج عندي، لكل واحد ريال أو ريالان، ونحن كثير حوالي أربعين حاج، وهم الذين بقيت لهم فلوس عندي حوالي عشرة حجاج، وعندما وصلنا إلى العراق تفرقوا ولم أعرف بيوتهم، أفيدونا جزاكم الله عنا خيراً، ما الذي أصنعه في هذه الفلوس؟","title":"حكم قضاء النقود القليلة لأناس مجهولين","answer":"الجواب: هذه الفلوس قليلة سهلة، في حكم المعفو عنه، إن أكلتها فلا بأس، وإن تصدقت بها فلا بأس، مادام ريال أو ريالين أمرها خفيف، والقاعدة أن الشيء القليل من اللقطات يسمح لآخذه، ولا حرج عليه في ذلك، وإن تصدقت بها عنهم، وأعطيتها بعض الفقراء فحسن، ولا حرج عليك في أكلها ولا في الصدقة بها. نعم.","link":"https://binbaz.org.sa/fatwas/5996/حكم-قضاء-النقود-القليلة-لاناس-مجهولين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_092/09202.mp3","categories":["اللقطة واللقيط"]},{"id":9023,"question":"رسالة وصلت إلى البرنامج من مكة المكرمة الزاهر وباعثها أخونا عبدالله علي الصاعدي أخونا يقول: وجدت خمسمائة ريال في إحدى الطرقات فلم أعرفها بل أكلتها في نفس اليوم الذي وجدتها فيه بحجة أنني أردها إلى صاحبها في حالة معرفتي له، والآن لم أجد صاحبها، كيف أتصرف جزاكم الله خيراً؟","title":"حكم لقطة المال إذا أكلت قبل التعريف","answer":"الجواب: الواجب تعريفها، فإذا كنت عرفتها سنة كاملة في كل شهر مرتين ثلاث: من له الدراهم.. من له الدراهم التي ضاعت منه في كذا وكذا في حارة كذا، في حي كذا، تعرفها في مجامع الناس في محل اجتماع الناس حول أبواب الجوامع في الأسواق التي فيها الاجتماع، فإذا مضى سنة على تعريفك لها فهي لك حلال لك، ومتى جاء صاحبها وعرفها بالصفات الخاصة تعطيه إياها، تكون عندك كأنها وديعة فإذا جاء أعطيته أياها.\nأما إذا كنت لم تعرفها بل أكلتها وسكت فإن الواجب عليك أن تتصدق بها في وجوه البر بالنية عن صاحبها؛ لأنك لم تأت بأسباب حلها وهو التعريف، أسباب حلها التعريف وأنت لم تعرفها فعليك أن تصدق بها عن صاحبها وهو يصله ثوابها بإذن الله عز وجل. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7181/حكم-لقطة-المال-اذا-اكلت-قبل-التعريف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14716.mp3","categories":["اللقطة واللقيط"]},{"id":9192,"question":"من حفر الباطن المستمع (م. ط. ف) بعث يسأل ويقول: ضاع لوالدي بعض من الإبل وذهب يبحث عنها وعندما وجدها وجد معها بعيرًا لا يعرفه ولا يعرف صاحبه، وجاء به مع إبله ومكث هذا البعير عندنا وقتًا طويلًا ولم يأت من يسأل عنه، فتوفي والدي رحمة الله عليه عام أربعة وثمانين، وبعد ذلك مات البعير، و هل على والدي شيء؟ وماذا يجب علي أن أفعل الآن حيث أني أريد أن أبرئ ذمة والدي؟ وكم القيمة التي يجب علي أن أدفعها إن كانت واجبة علمًا بأن هذا الشيء مضى عليه حوالي عشرون عامًا جزاكم الله خيرا؟","title":"حكم أخذ ضالة الإبل","answer":"الجواب: الواجب على والدك طرد هذا البعير وعدم إيوائه؛ لقول النبي ﷺ لما سئل عن ضالة الإبل : دعها فإن معها حذاءها وسقاءها ترد الماء وتأكل الشجر حتى يلقاها ربها، فالواجب عليه لما وجد هذا البعير مع إبله أن يطرده وألا يؤيه، لكن مادام أنه آواه مع إبله حتى مات البعير فلا أعلم عليكم شيئًا في ذلك إذا كنتم لم تسببوا في موته لا في شد ورحل ولا بغير ذلك، إنما هو مع الإبل يرعى معها ثم مات بدون عمل منكم ولا ظلم منكم ولا شيء، فلا أعلم شيئًا عليكم في ذلك. نعم.\nالمقدم: وتبرئة ذمة المتوفى ليس هناك في ذمته شيء؟\nالشيخ: ... ليس في ذمته شيء إلا الدعاء له بالمغفرة والرحمة؛ لأنه أخطأ في إيوائه ولكنه لم يعمل شيئًا في إتلافه.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7352/حكم-اخذ-ضالة-الابل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18103.mp3","categories":["اللقطة واللقيط"]},{"id":9531,"question":"يسأل أيضا ويقول: وجد راع في قريتنا عنزاً صغيرة كانت عمياء ومكسورة الرجلين وعلى وشك أن تموت، وأخذها وعاد بها إلى بيته فذبحها وسأل أصحاب القرية عن هذه العنز فلم يجد لها صاحب وبعد سلخها وزنها فوجد أن وزنها سبعة ونصف كيلو ووضعها في الثلاجة، وبعد مرور أسبوع وجد صاحبها فخيره بين ثمنها وبين أن يأخذ اللحم فاختار الثمن وهو غير راض عن ذبح عنزة، فهل على الراعي إثم فيما فعل أفيدونا أفادكم الله؟","title":"حكم من وجد شاة على وشك الموت فذبحها ثم جاء صاحبها","answer":"الجواب: إذا كان الواقع مثل ما ذكر السائل فليس عليه شيء؛ لأن هذه في حكم الميتة هذه منبوذة مستغنىً عنها، صاحبها في الغالب لا يريدها فالذي أخذها وأحسن إليها مأجور ولا عليه شيء، ومتى عرف ربها وطلبها ربها وأعطاه إياه فلا بأس والحمد لله أو أعطاه قيمتها فلا بأس؛ لأن هذه مطروحة معناها منبوذة معناها لا يرغب فيها، والشيء الذي ينبذه أهله لحقارته أو لأن مثله لا يرغب فيه إذا أخذه المؤمن فلا شيء عليه، مثل: عصا، مثل: حبل، مثل أشياء ما لها أهمية مثل خرقان النعال التي ليس لها قيمة وأشباه ذلك من الأشياء التي ليس لها قيمة يعني في نفوس أوساط الناس. نعم.","link":"https://binbaz.org.sa/fatwas/7701/حكم-من-وجد-شاة-على-وشك-الموت-فذبحها-ثم-جاء-صاحبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_245/24513.mp3","categories":["اللقطة واللقيط"]},{"id":10569,"question":"يقول في سؤال آخر: وجدت أختي الصغيرة خاتماً من ذهب في ساحة بيتنا، وهذا الخاتم ليس ملكاً لنا، فما الحكم في ذلك؟ مع العلم أننا لا نستطيع تعريفه سنة؟ أفيدونا أفادكم الله.","title":"حكم اللقطة لمن لا يستطيع تعريفها سنة","answer":"الجواب: الخاتم يختلف إذا كانت قيمته سهل يسيرة في البلد ولا تطلبها النفوس المتوسطة، يعني: ما يطلبها الإنسان يتعب فيها من ذوي الدخل المتوسط فإن هذه لا تعرف، يأخذها صاحبها ويستنفع بها واجدها والحمد لله.\nأما إذا كان الخاتم له قيمة كبيرة فهذا يجب تعريفه سنة كاملة، ولو في الشهر مرتين أو ثلاث، من له خاتم من له الخاتم، فإذا وجد من يعرفه وإلا فهو للذي وجدته، للمرأة التي وجدته يكون لها الخاتم.\nالمقدم: بنت صغيرة يقول.\nالشيخ: .... وليها، وليها أبوها أو أخوها يعرفها، يأمر بتعريفه ولو بالأجرة، وتسلم الأجرة من قيمة الخاتم إذا بيع، وإذا كانوا لا يستطيعون يعطونه إنسان يعرفه ولو بالأجرة هو الذي يعرف بالأجرة يقوم بذلك، هذا إذا كان له قيمة وله أهمية كيسوى مائتين ثلاث أربع، أما إذا كانت قيمته خمسين ريال أربعين ريال فهذا لا يحتاج إلى تعريف أمره بسيط؛ لأنه لو عرف أكل قيمته. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8745/حكم-اللقطة-لمن-لا-يستطيع-تعريفها-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_323/32305.mp3","categories":["اللقطة واللقيط"]},{"id":11132,"question":"هل تعرف ضالة الغنم؟","title":"حكم تعريف ضالة الغنم","answer":"الجواب:  يجب تعريفها، لقول النبي ﷺ: من آوى ضالة فهو ضال ما لم يعرفها، فإذا وجد ضالة من الغنم فعليه تعريفها كما يعرف النقود والأواني والملابس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9312/حكم-تعريف-ضالة-الغنم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_369/36912.mp3","categories":["اللقطة واللقيط"]},{"id":11272,"question":"من الجبيل المستمع عبد الرحمن خلف الحماد، رسالة وضمنها جمعًا من الأسئلة، في أحدها يقول: وجد أحد أصدقائي منذ عام تقريبًا مبلغ خمسمائة ريال سعودي دون أن يعلم حكم اللقطة، ولما عرف أنه كان لابد أن يعلن عنها وهو الآن يريد أن يتوب، ماذا يفعل ليكفر عن ذنبه هذا، وهل يعذر بجهله ويستغفر أم ماذا عليه جزاكم الله خيرًا؟","title":"حكم من وجد مالاً ولم يعرفه لجهله بالحكم","answer":"الجواب: المشروع له أن يعرفها سنة كاملة ولو طالت المدة، من له الدراهم التي ضاعت منه في سنة كذا في بلد كذا، لعل صاحبها يذكرها في مجامع الناس في محلات فيها اجتماع الناس عند أبواب الجوامع، أو في الأسواق التي فيها تجمع الناس، من له الدراهم التي ضاعت منه في محل كذا في سنة كذا، فإذا مضى سنة ولم تعرف فإنه يتصدق بها في وجوه البر يعطيها الفقراء؛ لأنه فرط ما يملكها لأنه أخر التعريف، أما إذا عرفها في سنتها ولم تعرف فهي له تكون ملكًا له، أما إذا فرط .... وتساهل يعرفها سنة فإن لم تعرف تصرف في وجوه البر وأعمال الخير صدقة لصاحبها، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9459/حكم-من-وجد-مالا-ولم-يعرفه-لجهله-بالحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37510.mp3","categories":["اللقطة واللقيط"]},{"id":11726,"question":"كثيرًا ما يجد الإنسان في طريقه بعضًا من المال القليل فيأخذه؛ لأنه يقول: وجدته في شوارع المدينة، فكيف أجد صاحب المال، هل عليه إثم في ذلك؟","title":"حكم اللقطة إذا كانت يسيرة","answer":"الجواب: إذا كان شيئًا يسيرًا لا تتبعه همة أوساط الناس، ولا يلتفت إليه؛ فلا بأس، مثل عصا لا قيمة لها، حبل لا قيمة له، درهمين إلى عشرة دراهم، أشباه ذلك، هذه أمرها سهل، ولا حرج في أخذها، أما الشيء الذي له أهمية، وله قيمة هذا عليه أن يعرفه لمعارفه في مجامع الناس، من له اللقطة الفلانية؟ من له الدراهم؟ من له البشت؟ من له النعل المعروف كذا يبين، يبين حتى إذا جاء من يعرف هذه اللقطة؛ سلمها له، إذا عرف صفاتها الخاصة الدقيقة؛ أعطاه إياها، أو أقام الدليل عليها، وإلا فليدعها، يأخذها غيره، أما أن يأخذ، ولا يعرف لا، لابد أن يعرف اللقطة -إذا كانت ثمينة لها أهمية- في مجامع الناس كل شهر مرتين ثلاث حتى يكمل السنة، فإذا تمت السنة؛ فهي له كسائر ماله، ومتى جاء صاحبها بعد ذلك أعطاه إياها، ولو بعد مدة طويلة، أو يوكل من يعرفها إنسان ... ينادي عليها كل شهر مرتين ثلاث في مجامع الناس؛ لعلها تظهر حتى يكمل السنة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9909/حكم-اللقطة-اذا-كانت-يسيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42107.mp3","categories":["اللقطة واللقيط"]},{"id":12974,"question":"أخيرًا يسأل ويقول: أرجو منكم -جزاكم الله خيرًا- توضيحًا شاملًا عن اللقطة بأنواعها، وخاصة لقطة الغنم؟","title":"أحكام اللقطة وأنواعها","answer":"الجواب:  النبي ﷺ سئل عن اللقطة من الإبل فقال: دعها معها حذاؤها وسقاؤها، ترد الماء، وتأكل الشجر حتى يلقاها ربها فالإبل لا تلقط، وهكذا ما في معناها من البقر وأشباهها مما يمتنع من صغار السباع. أما الغنم فإنها تلتقط، النبي ﷺ قال: خذها فإنما هي لك، أو لأخيك، أو للذئب فيأخذها ولا يدعها، وينشد عليها يعني: يطرب عليها، ينشد يقول: من له الشاة، من له العنز، من له التيس، وجدته في محل كذا وكذا، في يوم كذا وكذا، فإذا وجد من يعرفه؛ سلمه له، سنة كاملة، لقوله ﷺ: من آوى ضالة فهو ضال ما لم يعرفها فلابد من التعريف في العنز ونحوها، كالفصيل الذي ما يمتنع من السباع، وأشباه ذلك مما لا يمتنع من صغار الحيوانات. وهكذا لقطة الأموال كالذهب والفضة والأواني والملابس يعرفها بقوله: من له كذا وكذا، ولا يبين الصفات، فإذا جاء صاحبها، وعرف الصفات؛ سلمها له، أو أقام بينة، سلمها له سنة كاملة؛ لأن الرسول  قال: فليعرفها سنة يعني: ينادي عليها سنة في مجامع الناس، في الشهر مرتين ثلاثًا أربعًا، من له اللقطة، من له العنز، من له كذا، فإذا وجد من يعرفها أعطاها إياه، ثم هو بالخيار في العنز، إن شاء ذبحها وعرف قيمتها بمعرفة أهل الخبرة، وحفظ القيمة، وكتبها عنده، وكتب علاماتها وصفاتها، صفات العنز، أو الشاة، أو الخروف يضبط الصفات، وإن شاء باعها، وحفظ الثمن، وإن شاء أبقاها مع غنمه إذا كان ما فيها مشقة، ترعى مع غنمه حتى يجدها ربها. وهكذا الأواني وأشباهها يحفظها حتى يجدها ربها مع النداء عليها والتعريف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11191/احكام-اللقطة-وانواعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47008.mp3","categories":["اللقطة واللقيط"]},{"id":13182,"question":"بعد ذلك ننتقل إلى رسالة السائل (ل. أ. م) يقول: ما حكم تبني الأطفال؟ وما حكم إذا كانت هذه المرأة قد أرضعت ذلك الطفل، جزاكم الله خيرًا؟","title":"حكم تبني الأطفال","answer":"الجواب:  التبني لا يجوز في الإسلام، الله -جل وعلا- قال: ادْعُوهُمْ لِآبَائِهِمْ [الأحزاب:5] فإذا رباه تربية، ونسبه إلى أبيه؛ لا بأس، كونه يحسن فيه، ويربيه، وينفق عليه؛ لأنه يتيم لا أب له، أو لأنه مجهول، ما يعرف، فهذا من باب الإحسان، لكن لا ينسبه إليه، يربيه، ويحسن فيه، وينسب إلى اسم معبد لله، فلان ابن عبدالله، ابن عبدالرحمن، ابن عبدالمجيد.. إلى غير ذلك، ولا ينسبه لنفسه؛ لأن الله قال: ادْعُوهُمْ لِآبَائِهِمْ [الأحزاب:5] ولأن نسبته لنفسه يوهم أنه ولده، فقد يورث منه، وقد يرى أولاده أنه محرم للبنات.. إلى غير هذا من الفساد. فالمقصود أن التربية جائزة، كونه يربيه؛ لأنه مجهول، أو يتيم ما يعرف له أب، أو ما أشبه ذلك، فإنه يحسن إليه، وينفق عليه، مثل ما يقع في الحروب من ضياع الأولاد، وعدم وجود آبائهم وأمهاتهم، أو طفل يوضع في المسجد ما له أحد، فيأخذه ويحسن إليه، لا بأس من باب الإحسان، فيربيه وينفق عليه، ولكن لا ينسبه إلى نفسه، لا يقول: ولدي، بل ينسبه إلى عبد من عباد الله: عبدالله ابن فلان.. محمد ابن فلان .. صالح ابن فلان، يسميه أحد الأسماء الشرعية: صالح ابن عبدالله.. صالح ابن عبدالرحمن.. صالح ابن عبدالرحيم.. وما أشبهه، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11437/حكم-تبني-الاطفال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51118.mp3","categories":["اللقطة واللقيط"]},{"id":13354,"question":"هذا السائل يوسف محمد سوداني، ويقول في سؤاله: له غنم، وضمت هذه الأغنام واحدة ليست له، وصارت لها مدة طويلة من الزمن، وتكاثرت، ولم يعرف لها أحد ماذا يفعل بها؟","title":"ما يفعل من وجد غنمة ولا يعلم صاحبها؟","answer":"الجواب: هذه الغنم بين أمرين: إما أن يعرفها التعريف الشرعي سنة كاملة؛ لأن الغنم تُعرَّف، وإذا تم السنة ولم تُعرف؛ فهي ماله؛ لقول النبي ﷺ: هي لك، أو لأخيك، أو للذئب وقال: من آوى ضالة؛ فهو ضال ما لم يعرفها فإذا عرفها سنة؛ فهي له، أو يسلمها للحاكم، الحاكم الشرعي، والحاكم الشرعي يعمل فيها ما يرى من حفظها، أو بيعها، أو إدخالها بيت المال إذا لم يوجد لها أحد. المقصود: هو أن الحاكم الشرعي يتصرف في جعل من يُعرِّف، أو جعلها في بيت المال، ينظر في أشياء تحف بها، قد تكون مثلًا لها مدة طويلة، قد تكون يمكن أن تعرف. فالحاصل: أن الذي وجدها يعرفها سنة كاملة، فإذا لم تُعرف؛ فهي له، وإن تخلص منها، وأعطاها الحاكم، أو الأمير، أو اللجنة المعدة للقطات؛ برئ منها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11640/ما-يفعل-من-وجد-غنمة-ولا-يعلم-صاحبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_523/52311.mp3","categories":["اللقطة واللقيط"]},{"id":14058,"question":"يسأل أخونا سعد وهام من العراق فيقول: لي صديق في أحد الأيام أعطاني كتاب ديني، لكنه يقول: إنه أخذ هذا الكتاب من مكان لا يعرف صاحبه، فهل أدفع ثمن هذا الكتاب لأحد الفقراء؛ لأنه لم أشتره وأعتبره مغتصب؟ أم كيف أتصرف؟ جزاكم الله خيرا.","title":"ما يفعل من أخذ كتابًا من مكان لا يعرف صاحبه؟","answer":"الجواب: الواجب أن ترده إلى صاحبه، وهو يرده إلى المكان الذي أخذه منه، الواجب عليك أن ترده إلى الذي أعطاك الكتاب، وتقول له: يجب عليه أن يرده إلى مكانه، وليس له أخذ كتاب بغير حق، إلا إذا سمح صاحبه بذلك، أو أعطاه ثمنه فلا بأس، فإن لم يتيسر لك ذلك، بأن لم تحصل الرجل حتى تعطيه الكتاب؛ فلا مانع من أن تصدق بقيمته، أو تجعله في مكتبة عامة ينتفع به الناس، مع التوبة والاستغفار من أخذه، من أخذك إياه من هذا الشخص الذي ذكر لك أنه أخذه بغير حق، والله المستعان. نعم.\nالمقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12483/ما-يفعل-من-اخذ-كتابا-من-مكان-لا-يعرف-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_608/60804.mp3","categories":["اللقطة واللقيط"]},{"id":14127,"question":"يقول هذا السائل: هل اللقطة عند الإشهار بها سنة كاملة يجوز الاستفادة منها وأخذها أم لا؟","title":"هل تحل اللقطة بعد تعريفها سنة؟","answer":"الجواب: نعم، إذا وجد لقطة وهي دراهم أو متاع وعرفه سنة كاملة فإنها تحل له تكون من ماله إذا لم تعرف، إذا عرفها سنة كاملة فلم تعرف صارت كسائر ماله، كما أخبر النبي ﷺ، أمر أن من وجد لقطة أن يعرفها سنة، فإن عرفت وإلا فهي له كسائر ماله، كل شهر مرتين ثلاث أربع في مجامع الناس، من له اللقطة؟ من له الدراهم؟ من له الجنيهات؟ من له الملابس؟ من له الأواني؟ من له الشاة؟ من له العنز؟ يبين ويخفي بعض الصفات حتى يجيء من يعرف صفاتها الخاصة، فإذا جاء من يعرف صفاتها الخاصة أعطاها إياه، فإن مضت السنة ولم يأت أحد فإنه يملكها، إلا إذا كانت من لقطة الحرم، لا. لقطة الحرم لا تملك، وهكذا لقطة المدينة لا تملك، أما غير الحرمين تملك إذا عرفها سنة.  وأما الإبل فلا، الإبل والبقر لا تملك، يعني: لا يزال يعرفها؛ لأن معها سقاها، ترد الماء وتأكل الشجر، لكن إذا كانت اللقطة من الغنم أو من النقود أو من الأمتعة كالملابس والأواني فلا بأس يعرفها سنة كاملة في غير الحرمين فإن عرفت وإلا فهي له، إذا كان يعرفها كل شهر مرتين ثلاث أربع، يعني: يجتهد في تعريفها حتى يبرئ ذمته. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12568/هل-تحل-اللقطة-بعد-تعريفها-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52214.mp3","categories":["اللقطة واللقيط"]},{"id":14337,"question":"المستمع عبد الرحيم حماد من السودان بعث برسالة يقول فيها: شخص مغترب عن بلده، وجد مالًا في طريق شبه خال، أي: صحراء، وأخذه وهو لا يحب الحرام ولكنه في نفس الوقت محتاج، هل هذا المال حلال أم حرام؟ وماذا عليه أن يفعل تجاهه؟","title":"ما يجب على من وجد مالا في مكان شبه خالٍ؟","answer":"الجواب: عليه أن يعرفه سنة كاملة إذا كان له قيمة يعرفه سنة كاملة، في مجامع الناس عند أبواب الجماعة وقت صلاة الجمعة، في الأسواق اللي فيها جمع الناس، من له اللقطة يسميها إن كانها مال ذهب أو فضة يقول: الذهب والفضة حلية، إن كانها بشت غالي أو شبه ذلك، يبين حتى إذا جاء من يعرف صفاتها سلمها له، لكن لا يبين الصفات، يقول: من له السلعة الفلانية، من له الحاجة الفلانية ويحفظ صفاتها الخفية يحفظها ويكتمها فإذا جاء من يعرفها سلمها له، فإن تمت السنة ولم يأت أحد فهي له، سبيلها سبيل ماله، ومتى عرفت بعد ذلك سلمها لصاحبها ولو بعد سنوات، لكن بعد السنة تكون ملكًا له يتصرف فيها كسائر ماله، وإن شق عليه حفظها باعها وحفظ ثمنها، إذا كان حفظها يشق عليه باعها في سوق من يزيد وحفظ ثمنها حتى تعرف فإذا عرفت سلم له الثمن.\nالمقدم: جزاكم الله خيرًا، سوق من يزيد شبه الحراج ...\nالشيخ: يعني الحراج إيه.\nالمقدم: الحراج؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12819/ما-يجب-على-من-وجد-مالا-في-مكان-شبه-خال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_623/62303.mp3","categories":["اللقطة واللقيط"]},{"id":14344,"question":"المستمع عبد الرحيم حماد من السودان بعث برسالة يقول فيها: شخص مغترب عن بلده، وجد مالًا في طريق شبه خال، أي: صحراء، وأخذه وهو لا يحب الحرام ولكنه في نفس الوقت محتاج، هل هذا المال حلال أم حرام؟ وماذا عليه أن يفعل تجاهه؟","title":"ما يجب على من وجد مالا في مكان شبه خالٍ؟","answer":"الجواب: عليه أن يعرفه سنة كاملة إذا كان له قيمة يعرفه سنة كاملة، في مجامع الناس عند أبواب الجماعة وقت صلاة الجمعة، في الأسواق اللي فيها جمع الناس، من له اللقطة يسميها إن كانها مال ذهب أو فضة يقول: الذهب والفضة حلية، إن كانها بشت غالي أو شبه ذلك، يبين حتى إذا جاء من يعرف صفاتها سلمها له، لكن لا يبين الصفات، يقول: من له السلعة الفلانية، من له الحاجة الفلانية ويحفظ صفاتها الخفية يحفظها ويكتمها فإذا جاء من يعرفها سلمها له، فإن تمت السنة ولم يأت أحد فهي له، سبيلها سبيل ماله، ومتى عرفت بعد ذلك سلمها لصاحبها ولو بعد سنوات، لكن بعد السنة تكون ملكًا له يتصرف فيها كسائر ماله، وإن شق عليه حفظها باعها وحفظ ثمنها، إذا كان حفظها يشق عليه باعها في سوق من يزيد وحفظ ثمنها حتى تعرف فإذا عرفت سلم له الثمن.\nالمقدم: جزاكم الله خيرًا، سوق من يزيد شبه الحراج ...\nالشيخ: يعني الحراج إيه.\nالمقدم: الحراج؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12819/ما-يجب-على-من-وجد-مالا-في-مكان-شبه-خال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_623/62303.mp3","categories":["اللقطة واللقيط"]},{"id":14361,"question":"يقول: حصل وأن وجدت ماعزة حاملة، وعليها وسم عمي، وولدت ولا أعرف أنه يملكها أو باعها، فذبحت جناها، وبعد سنة ضاعت، أرجو فتواكم.","title":"حكم من وجد لقطة ثم ضاعت منه","answer":"الجواب: إذا كنت لم تسأل عمك ولم تعرف أنها ملكه، وعليها وسم عمك، فليس عليك حرج -إن شاء الله- إلا أنك كان ينبغي لك الاحتياط، وعدم ذبح الجنى، أما الآن ما دمت لم تجد لها مطالبًا، ووسم عمك فليس عليك شيء، وفي إمكانك سؤال عمك إذا كان موجودًا، أو سؤال ذريته ورثته هل يسمحون لك، وهل هي معزهم، أو قد باعوها على أحد، أو أعطوها أحدًا، تسأل وتأخذ بالحيطة إذا أمكنك ذلك، فإن لم يمكن فاغرمها، اغرم ما ذبحت لورثة عمك إن كان قد مات، وأما هي إذا كنت لم تفرط فيها ولم تعمل فيها ما يسبب موتها فليس عليك بها شيء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12841/حكم-من-وجد-لقطة-ثم-ضاعت-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_487/48708.mp3","categories":["اللقطة واللقيط"]},{"id":14676,"question":"رسالة وصلت إلى البرنامج من المستمع نوري أحمد محمد، الأخ نوري يقول: أنا كنت مقيمًا بصحراء لرعي الأغنام، ووجدت جملًا أنا وأحد زملاء المهنة، وتركت هذا الجمل مع زميلي، وهو الذي كان يقوم برعايته، وبعد ذلك بعناه بمبلغ ثلاثمائة جنيه، أخذت أنا مائة والباقي لزميلي، ما حكم ما فعلنا؟جزاكم الله خيرًا، علمًا بأنا عرفنا بلد ذلك الجمل لكنا لا نعرف صاحبه بالضبط.","title":"ما حكم من وجد جملًا ضالًا فأخذه وباعه؟","answer":"الجواب: على كل حال قد أخطأتما في أخذ الجمل، والواجب ترك الجمل، وعدم أخذه؛ لقول النبي ﷺ لما سئل عن ضالة الإبل قال للسائل: دعها، فإن معها حذائها وسقائها، ترد الماء، وتأكل الشجر، حتى يجدها ربها وغضب -عليه الصلاة والسلام-، فدل ذلك على أن ضالة الإبل لا يجوز أخذها بل تترك؛ لأنها دابة قوية تمنع صغار السباع عنها، وتعيش على الرعي والشرب من المياه التي تحصلها في البراري، وهي لها صبر على الظمأ، وقوة على المشي، فلا يجوز أخذها، بل يجب تركها. إلا إذا كانت في محل خطير مسبعة للأسود والنمور ونحو ذلك مما يفترسها، أو في بلاد يأكل أهلها الضوال، فإن من وجدها من المحسنين يأخذها ويسلمها لولي الأمر، ولي أمر المسلمين، حتى يحفظها لصاحبها في رعايا المسلمين، أو يبيعها ويحفظ صفاتها حتى يجدها ربها، ويسأل عنه في مظان محاله، أو يجعلها عند من يرعاها حسب ما يراه مصلحة في ذلك. أما الواجد فليس له أن يجعلها مع إبله، وليس له أن يبيعها، وليس له أن يأكل ثمنها، بل عليه أن يسلمها لولي الأمر حتى يحفظها ولي الأمر مع رعايا المسلمين، مع إبل المسلمين، أو مع راع خاص، أو يبيعها على حسب ما يراه هو مما هو أصلح لصاحب الناقة، مع حفظ صفاتها ووسامها وسنها حتى يعرف ربها. أما أنتما فعليكما السؤال عن صاحب الضالة في محله الذي تعرفون، فإن عرف سلم له المال، مع التوبة إلى الله، والندم على ما فعلتما، وإن لم يعرف فعليكما الصدقة بالثمن للفقراء والمساكين بالنية عن صاحب الجمل، عليكم أن تتصدقوا بالمال، ولا يحل لكم السكوت، ولا أكل المال، بل الواجب الصدقة به بالنية عن صاحب الجمل عن مالكه، والله يأجره عليه، وتصله الصدقة حيًا أو ميتًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13175/ما-حكم-من-وجد-جملا-ضالا-فاخذه-وباعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_628/nour_62805.mp3","categories":["اللقطة واللقيط"]},{"id":14934,"question":"إذًا السؤال الأخير في لقائنا هذا من (ع. ك) من العراق يقول فيه: إنني كنت أشتغل في شركة أجنبية ليس عراقية، بتاريخ سنة اثنين وسبعين، يعني: اثنين وتسعين، وبعد انتهاء الشركة من عملها أخذوا بعض الأغراض الزائدة بإلقائها في منطقة تحت أشعة الشمس، ومطر الشتاء، وإنني أخذت من ذلك الأغراض، بعد تقريب أربع سنوات جاءت شركة واشتغلت فيها، وذكرت تلك الأغراض، وطلبوا مني شراءها، لحاجتهم بها، وبعتها بملغ مائة وخمسين دينار عراقيًا، وهل تعتبر حرام؟ وكيف أتخلص منها؟ لأنني تبت إلى الله توبة نصوح -إن شاء الله تعالى-.","title":"حكم من أخذ شيئًا مما ألقته الشركة بعد انتهاء عملها؟","answer":"الجواب: إذا كانوا ألقوها راغبين عنها، ما لهم فيها حاجة، راغبين عنها، يريدون أن يأخذها من شاء فلا بأس، إذا كان ألقوها يعني: راغبين عنها، ما لهم فيها حاجة، يريدون الناس يأخذونها، يريدون أن الناس يأخذوها فلا بأس، من أخذ شيئًا فلا حرج عليه. أما إن كان وضعوها ليرجعوا إليها، أو يوكلوا عليها من يبيعها، أو ما أشبه ذلك، يعني: ما تركوها رغبة عنها، ولكن تركوها في المكان هذا ليتصرفوا فيها بأنفسهم، أو بوكلائهم، فالذي أخذ منها يعيده إليهم إلى وكلائهم، فإن كان ما وجد لهم وكلاء، ولا حصل من يقوم مقامهم، يتصدق بهذا على بعض الفقراء، ويكفي.","link":"https://binbaz.org.sa/fatwas/13446/حكم-من-اخذ-شيىا-مما-القته-الشركة-بعد-انتهاء-عملها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_647/nour_64710.mp3","categories":["اللقطة واللقيط"]},{"id":15119,"question":"المستمع: حتمان فارس الحطيم، من بلدة الحومية، بعث يسأل، ويقول: هل اللقطة تحل للذي لقطها أم لا تحل؟جزاكم الله خيرًا.","title":"هل تحل اللقطة لملتقطها؟","answer":"الجواب: اللقطة إن كانت في الحرم، مكة والمدينة لا تحل، عليه أن يعرفها دائمًا حتى يجد ربها، سواءً دراهم، أو متاع آخر كالبشت أو غيره من المتاع. أما في غير الحرم يعرفها سنة، فإن عرفت وإلا فهي له، أما في الحرم لا، في مكة والمدينة يعرفها أبدًا، فإن شق عليه يسلمها للجنة التي في مكة والمدينة، يقول: هذه لقطة وجدتها في المحل الفلاني، وهم يقومون بالتعريف، ويتولون أمرها، وإلا فليعرفها هو بنفسه، أو بوكيله حتى تعرف، ولو بقي سنتين أو ثلاث أو أكثر يعرفها؛ حتى يوجد ربها، أو يسلمها للجنة. أما إذا كان في غير مكة والمدينة، فإنه يعرفها سنة كما أمر النبي ﷺ، قال في مكة: لا تحل ساقطتها إلا لمعرف يعني: منشد لها، يعرفها: من له الدراهم؟ من له الشنطة؟ من له كذا؟ من له كذا؟ في مجامع الناس. أما في غير مكة والمدينة، يعرفها بمجامع الناس: من له كذا؟ من له كذا؟ من له اللقطة؟ من له الشاة؟ من له العنز؟ من له البشت؟ من له كذا؟ يعرف، يبين، يخلي علامات عنده، العلامات الخفية يخليها عنده، لا يبينها، فإذا جاء من يعرفها، يقول: ما صفاتها؟ علمني صفاتها، فإذا عرف صفاتها، أعطاها إياه، وإن شك في الأمر طلب البينة عليه، حتى يحضر بينة، أن هذه ضائعة له، وأنها ملكه، وإذا عرف الصفات الدقيقة الخفية عرفها يعطيه إياه؛ لأن الرسول ﷺ أمر بهذا، أمر من وجد اللقطة أن يعرفها سنة، ويعرف عفاصها إن كان لها عفاص ووكائها، يعني: خرقتها إن كانت النقود في خرقة، أو في كيس، أو في ظرف، يعرف الظرف، ويعرف فئات الدراهم، ما هي؟ يضبطها ويعرفها، فإذا جاء من يعرفها أعطاه إياه سنة كاملة، ويعرف عددها: ألف، ألفين، ثلاث، يعرف عددها، فإذا مرت السنة، وما جاءه أحد، فهي له. وتكون كالوديعة عنده، متى عرف ربها، ولو بعد سنتين، أو ثلاث، أعطاه إياه كالدين عليه، وإذا لم تعرف، فهي ماله بعد السنة، النبي ﷺ قال: فإن لم تعرف فأنفقها فسبيلها سبيل مالك، قال: ولتكن وديعة عندك يعني: كالوديعة، يحفظها ويتصرف فيها، لكن متى جاء ربها وعرفها، ولو بعد سنتين أو ثلاث يعطيه إياه كأنها دين، لكن يعرفها كثير كل شهر مرتين ثلاث أكثر، من له الضائعة؟ من له الدراهم؟ ما يبين عددها، يقول: من له الدراهم؟ من له العنز؟ من له البشت؟ من له كذا؟ من له كذا؟ يبين الشيء حتى يفطن له صاحبه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13619/هل-تحل-اللقطة-لملتقطها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49503.mp3","categories":["اللقطة واللقيط"]},{"id":15226,"question":"المستمع (ع. م. م) من الرياض، يقول: سبق وأن أخذت شاة مع ولدها؛ وذلك قرب البلد، أنا وبعض الزملاء؛ وذلك له عشر سنوات، ما هو الواجب علينا الآن أن نتصرف؟جزاكم الله خيرًا.","title":"حكم ضالة الإبل والغنم","answer":"الجواب:  إذا كنت لم تعرفها سنة كاملة في مجامع الناس، من له الشاة وطفلها في كل شهر مرتين أو ثلاث، أو أكثر إذا كنت ما فعلت هذا، فعليك أن تتصدق بقيمتها، وقيمة ولدها بالنية عن مالكها، مع التوبة إلى الله ، تخرج قيمتها ذاك الوقت، وقت أكلها وذبحها، وتتصدق بها على الفقراء والمساكين، وتنويها عن صاحبها، وصاحب طفلها، مع التوبة إلى الله، والندم والعزم على أن لا تعود إلى مثل هذا؛ لأن الواجب على من وجد لقطة أن يعرفها، كما قال النبي ﷺ: من آوى ضالة فهو ضال ما لم يعرفها فالضالة: ما يكون من الحيوانات كالغنم، فإذا لقطها الإنسان يعرفها سنة كاملة، فإن لم تعرف فهي له، ومتى عرفت بعد ذلك سلمها أو قيمتها لصاحبها، أما الإبل فلا تلتقط، بل تترك لأنها معها سقاؤها وحذاؤها، ترد الماء، وتأكل الشجر، حتى يلقاها ربها وهكذا البقر؛ لأنها كذلك تمنع عن نفسها الذئب، ونحوه. أما الحيوان الذي لا يمنع عن نفسه كالخيل والحمر والبغال، فهذه تلتقط مثل الشاة، وتعرف إذا وجدت ضائعة تعرف من له الحمار، من له البغل، من له الخيل، من له الشاة، سنة كاملة، فإن لم تعرف ملكها، ولكن متى عرف صاحبها بعد ذلك، ولو بعد السنة ردها إليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13722/حكم-ضالة-الابل-والغنم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_497/49703.mp3","categories":["اللقطة واللقيط"]},{"id":16884,"question":"سؤاله الأخير يقول فيه: عندما يجد الإنسان في طريقه، أو في عقار يملكه مبلغًا من المال، أو شيئًا ماديًا يعادل مبلغًا من المال، ففي هذه الحالة هل يجوز لهذا الشخص التصرف فيما وجد؟ أم أنه يتبرع به، وذلك في حالة عدم وجود صاحب لهذا المال؟ أرجو التوضيح، جزاكم الله خيرًا كثيرًا، وعلمًا وفيرًا.","title":"حكم اللقطة إذا لم يعلم صاحبها","answer":"الجواب: هذا يعتبر لقطة، إذا وجد في الطريق، أو في ملكه دراهم، أو متاعًا آخر سقط من بعض الزوار، أو من بعض الناس في الطريق؛ هذا يعتبر لقطة، سئل النبي ﷺ عن ذلك، فقال ﷺ: عرفها سنة، فإن لم تعرف فهي لك فإذا كان الشيء الموجود له أهمية، مثل مائة ريال، ألف ريال، ألفين ريال، شنطة تساوي مالًا كثيرًا، سيفًا، خنجرًا، زولية، غير ذلك، شيء له أهمية، ينادي عليه في مجامع الناس: من له الزولية؟ من له الشنطة؟ من له السيف؟ من له الدراهم الواقعة في محل كذا وكذا؟ في الشهر مرتين.. ثلاثًا.. أربعًا، ينادي عليه، أو يخلي من ينادي عليه من الثقات في مجامع الناس، المحلات التي فيها اجتماع الناس في أسواق البيع والشراء، أو بعد صلاة الجمعة، من له هذا الشيء؟ ولا يبين الصفات، حتى يجي صاحبه ويبين، من له الشنطة؟ من له السيف؟ من له الدراهم؟ وإذا جاء من يقول: إنها لي يسأله عن الصفات، وايش صفات الشنطة؟ يضبط العلامات، يضبطها ضبطًا جيدًا، ويضبط الدراهم، هي أمهات خمس، خمسة، أمهات عشرة، فئة خمسمائة، أرقامها، يضبط حتى يسأله عما يدل على صدقه، فإذا عرفها؛ أعطاه إياه. فإن مضت سنة، ولم تعرف؛ فهي له، يستنفقها، ومتى جاء صاحبها، وعرفها أعطاه إياها، كالدين تصير عنده كالدين، متى جاء صاحبها؛ أعطاه إياه إذا عرفها، هكذا أمر النبي ﷺ إلا إذا كانت اللقطة في مكة لا، أو في المدينة لا، لقطة مكة، والمدينة لا تملك، لا بد من تعريفها دائمًا، النبي  قال: ولا تحل ساقطتها إلا لمعرف يعني: مكة، وقال في المدينة ﷺ: إني حرمت المدينة كما حرم إبراهيم مكة. فالواجب على من وجد لقطة في المدينة، ومكة أن يعرفها أبدًا أبدًا، لا يملكها، فإن لم يعرفها؛ أعطاها للجهة المختصة في مكة، والمدينة التي تسلم لها اللقطة، وإذا لم يعرف اللجنة؛ سلمها للمحكمة الشرعية... المحكمة، وأخذ وصلًا بذلك، والمحكمة هي التي تسلمها للجنة، واللجنة يراجعها الناس، يراجعونها، ويسألونها عن لقطاتهم. فالمقصود: أن مكة، والمدينة لا تملك لقطتهما، بل لا بد من التعريف عليها دائمًا دائمًا حتى يوجد ربها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15637/حكم-اللقطة-اذا-لم-يعلم-صاحبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_825/nour_82503.mp3","categories":["اللقطة واللقيط"]},{"id":16903,"question":"بعد هذا رسالة وصلت إلى البرنامج من المملكة الغربية محافظة..... باعث الرسالة المستمع مصطفى بن محمد بن إبراهيم، الأخ يسأل سماحتكم يقول: وجدت في الطريق مبلغًا من المال، ولا أعلم كيف أصنع به، وجهوني كيف أتصرف؟ هل يبقى معي؟ أو أتصدق به؟ جزاكم الله خيرًا.","title":"كيفية التصرف في اللقطة","answer":"الجواب: عليك أن تعرفه في مجامع الناس، تقول: وجدت مالًا في الطريق الفلاني، وفي المحل الفلاني، نقودًا، دولارات، دينارات، ريالًا سعوديًا، إلى غير ذلك توضح، فإذا جاءك من يعرفها، وأن عددها كذا، وجملتها كذا؛ تعطيه إياه، وإن مضى سنة ما جاء أحد؛ خذها لك، هكذا أمر النبي ﷺ بالتعريف سنة كاملة، تعرف في مجامع الناس عند أبواب الجوامع، في الأسواق، من له كذا؟ من له كذا؟ في الشهر مرتين، ثلاثًا، أكثر حتى تكمل السنة، فإذا تمت السنة، ولم يأت أحد؛ فهو لك، إلا إن يكون ضعيفًا زهيدًا لا قيمة له؛ هذا لك، ما يحتاج تعريف، كالعشرين ريالًا، عشرة ريالات، ثلاثين ريالًا، هذه أمرها خفيف، ما تحتاج إلى تعريف، أمرها سهل، لك أن تأخذها ولك أن تدعها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15661/كيفية-التصرف-في-اللقطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71910.mp3","categories":["اللقطة واللقيط"]},{"id":18015,"question":"من أحد الإخوة المستمعين رسالة ضمنها سؤالًا يقول: انضم إلى أغنامي عشر شياه وبحثت عن صاحبها فلم أجده، ولدت هذه الأغنام بنعاج كثيرة فذبحت من أطرافها هل يجوز لي ذلك أو لا؟","title":"وجوب التعريف بضالة الغنم سنة كاملة","answer":"الجواب: الواجب عليك التعريف سنة كاملة؛ لقول النبي ﷺ: من آوى ضالة فهو ضال ما لم يعرفها رواه مسلم في الصحيح، هذا وعيد شديد، والتعريف سنة: من له النعاج، في مجامع الناس، محلات مجامع الناس على المياه إن كان في البر، أو في البلدان التي حولك كالأسواق التي تجمع الناس بعد الجمعة، أو في أوقات أخرى في الشهر مرتين ثلاث أربع كل شهر تخلي من ينادي عليها. فإذا مضت السنة ولم يوجد أحد فهي لك ونتاجها لك، نتاجها بعد السنة لك، أما نتاجها في السنة سنة التعريف هي لصاحبها، فإذا عرف أخذها ونتاجها في السنة، أما نتاجها بعدما ملكتها فهو لك، ومتى عرف صاحبها أعطيته الأصل والنتاج الذي وقع في السنة، أما النتاج الذي بعد السنة فهو لك، الذي حملت فيه بعد السنة. والخلاصة: أن عليك التعريف سنة كاملة في مجامع الناس وإذا كنت في البرية في مجامع الناس على المياه من له النعاج، من له الغنم، حتى يسمع صاحبها الخبر فلعلك تجده، فإذا مضت سنة ولم يوجد فهي لك هي ونتاجها، ومتى وجد صاحبها أخذها وأخذ نتاجها الأول نتاجها الذي في السنة، أما النتاج الذي حملت به بعد السنة بعدما ملكتها فهو لك. والواجب عليك في هذا التوبة والاستغفار إذا كنت قصرت، وعليك أن تعرف سنة كاملة لعل صاحبها يجدها، فإن لم تفعل فأنت آثم وليست حلالًا لك بل يجب أن تسلمها لولي الأمر، ولي الأمر أمر المسلمين، المحكمة التي حولك حتى تبيعها وتحفظ ثمنها لصاحبها لعله يوجد بعد حين، أو يصرف في مصارف بيت المال المصارف الخيرية من بيت المال؛ لأنك أخطأت في عدم التعريف. نعم. المقدم: جزاكم الله خيرًا، كيف تشرحون حديث رسول الله ﷺ: هي لك أو لأخيك أو للذئب سماحة الشيخ؟ الشيخ: لما سئل عن الشاة قال: هي لك أو لأخيك أو للذئب يعني: خذها، قال: خذها هو يأخذها لكن يعرفها لا يتركها يأكلها الذئب ولكن يأخذها ويعرفها؛ لقوله ﷺ: من آوى ضالة فهو ضال الضالة: الحيوان الذي يضل عن صاحبه، والغنم تؤخذ، أما الإبل لا تؤخذ، الإبل تدافع عن نفسها والبقر لكن الغنم ما تدافع عن نفسها يأكلها الذئب، فالواجب أخذها وتعريفها لا يتركها للذئب. المقدم: إذًا أخذها للتعريف؟ الشيخ: للتعريف، فإن لم تعرف ملكها بعد ذلك. نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17059/وجوب-التعريف-بضالة-الغنم-سنة-كاملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85010.mp3","categories":["اللقطة واللقيط"]},{"id":19182,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: (أ. ع) سوداني مقيم في المملكة، يقول: إنني منذ فترة طويلة كنت أرعى الغنم، وجاء بين غنمنا عناق فذبحتها أنا وراعٍ معي وأكلناها، ثم بحثنا عن صاحبها لنعطيه ثمنها فلم نجده، وثمنها في ذلك الوقت يصل إلى خمسة وعشرين جنيهًا سودانيًا فكيف توجهوننا الآن جزاكم الله خيرًا؟","title":"حكم من وجد عناقًا فذبحها وأكلها","answer":"الجواب: عليك أن تتصدق أنت وصاحبك بقيمتها بالنية عن صاحبها، إذا كانت المدة طويلة، أما إن كانت المدة قريبة فعليك أن تعرفها سنة كاملة: من له العناق من له العناق في مجامع الناس، لعلها تعرف فمتى عرفها فأعطوه قيمتها، وإذا لم تعرف فلا شيء عليكم، وأما إن كانت المدة طويلة قد فات وقت التعريف قد نسيها صاحبها، أو ذهب عن المكان، أو ما أشبه ذلك، فالأحوط لك ولصاحبك أن تصدقا بقيمتها بالنية عن صاحبها، أما إذا أمكن تعريفها سنة كاملة، لعل صاحبها يعرفها فعرفها سنة كاملة في مجامع الناس: من له العناق من له العناق التي وجدت في محل كذا وكذا؛ لعلها تعرف فإذا عرفت تعطي من طلبها وإن سمح فلا بأس. أما إن كانت المدة طويلة قد مضى دهر طويل؛ فالغالب أن صاحبها لا يكون موجودًا، ولا يلزم التعريف حينئذ فتتصدق بثمنها عنه بالنية عن صاحبها، وإذا عرفتها احتياطًا لعله يعرف، فهذا أيضًا أكمل وأطيب وأحوط. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18360/حكم-من-وجد-عناقا-فذبحها-واكلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_737/nour_73716.mp3","categories":["اللقطة واللقيط"]}]
